import forecastJson from './qualification-forecast.json'
import { getTournaments } from '@/services/api'
import type { ForecastCategory, ForecastEntry, Kenya1Race, PlayerForecast } from './qualification-odds'

// Generated by scripts/update_forecast.py; the deploy workflow rejects a stale file.
// Import only from server components so the full file isn't shipped to the browser.
interface ForecastFile {
  season: number
  after: { id: string; name: string }
  sims: number
  remaining: Array<{ id: string; name: string; start_date: string }>
  tournaments: Record<string, number>
  categories: Record<ForecastCategory, {
    cutoff: Array<number | null>
    // The median cutoff published before the latest event.
    cutoff_before?: number
    players: Record<string, ForecastEntry>
    kenya1?: Kenya1Race
  }>
}

const forecast = forecastJson as unknown as ForecastFile

// Results edited outside the release workflow (e.g. the production admin page) reach the API
// without a new forecast, so only show odds while the API's tournaments match the ones modelled.
// Doesn't depend on the player, so pages can run it alongside their player request.
export async function forecastMatchesResults(season: number): Promise<boolean> {
  if (season !== forecast.season) return false
  try {
    const tournaments = await getTournaments({ season })
    const modelled = Object.keys(forecast.tournaments)
    return tournaments.length === modelled.length &&
      tournaments.every(t => forecast.tournaments[t.id] === t.results)
  } catch {
    return false
  }
}

export function getCategoryForecast(
  category: ForecastCategory,
  season: number,
  matchesResults: boolean
): Record<string, ForecastEntry> | null {
  if (season !== forecast.season || !matchesResults) return null
  return forecast.categories[category].players
}

export function getPlayerForecast(
  fideId: string | null | undefined,
  season: number,
  matchesResults: boolean
): PlayerForecast | null {
  if (!fideId || season !== forecast.season || !matchesResults) return null

  // Only women have Ladies odds, and a woman who makes both teams takes the Ladies place.
  const order: ForecastCategory[] = ['ladies', 'open']
  const categories = order.flatMap(category => {
    const { players, cutoff, cutoff_before: cutoffBefore, kenya1 } = forecast.categories[category]
    const entry = players[fideId]
    return entry ? [{
      category,
      entry,
      cutoff,
      ...(cutoffBefore !== undefined ? { cutoffBefore } : {}),
      ...(entry.p_kenya1 !== undefined && kenya1 ? { kenya1 } : {}),
    }] : []
  })
  if (categories.length === 0) return null

  return {
    fideId,
    season: forecast.season,
    afterEvent: forecast.after.name,
    sims: forecast.sims,
    categories,
  }
}
